drafts.2:
h1 {
  text-align: center;
  font-size: 32px;
  color: #4338ca;
}

p {
  text-align: center;
}

drafts.4:
ul {
  display: flex;
  list-style: none;
  padding: 0;
}

li {
  display: inline;
  margin-right: 15px;
}

a {
  text-decoration: none;
}

drafts.5:
table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  border: 1px solid #333;
  padding: 8px;
}

th {
  background-color: #bfdbfe;
  color: grey;
}

drafts.6:
form {
  background-color: #eeeeee;
  padding: 16px;
  border-radius: 10px;
}

input,
select,
textarea {
  width: 100%;
  box-sizing: border-box;
}

drafts.7:
.card {
  max-width: 360px;
  margin: 20px auto;
  background-color: white;
  border: 1px solid #ccc;
  border-radius: 12px;
  box-shadow: 0 4px 12px #0f172a18;
  padding: 16px;
}

.card h2 { color: #3730a3; margin-top: 0; }
.card a { color: #4f46e5; }
